{
  "root_causes": [
    {
      "service": "ts-admin-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "WITH s AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT p, service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95_ms, AVG(duration/1e6) avg_ms FROM s WHERE service_name='ts-admin-user-service' AND span_name IN ('AdminUserController.getAllUsers','GET /api/v1/adminuserservice/users','GET') GROUP BY ALL ORDER BY 3,1", "claim": "getAllUsers and its GET server span rose from about 7-10 ms p95 to about 1,670 ms; the outgoing GET client span stayed around 6 ms."},
        {"kind": "trace", "sql": "SELECT time, service_name, span_name, parent_span_id, duration/1e6 AS ms FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' AND duration > 1000000000 LIMIT 1) ORDER BY time", "claim": "In a slow trace, getAllUsers starts at 06:07:06.25 but its outgoing call starts at 06:07:07.91, so about 1.66 s is spent inside the service before downstream calls."},
        {"kind": "metric", "sql": "SELECT metric, AVG(value) v FROM abnormal_metrics_sum WHERE service_name='ts-admin-user-service' AND metric IN ('k8s.pod.uptime') GROUP BY 1", "claim": "Pod uptime is continuous, with no restart or new pod; CPU and memory stayed within normal ranges for this service."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-admin-user-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "WITH s AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.p, par.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(par.duration/1e6,0.95) caller_p95_ms FROM s c JOIN s par ON c.parent_span_id=par.span_id AND c.trace_id=par.trace_id WHERE c.attr_span_kind='Server' AND c.service_name IN ('ts-admin-user-service','ts-ui-dashboard') AND c.span_name LIKE '%adminuserservice/users%' GROUP BY ALL ORDER BY 1,2", "claim": "ts-ui-dashboard's GET /adminuserservice/users p95 rose to about 1,677 ms, matching the 1,673 ms of its ts-admin-user-service callee."}]}
  ]
}

